/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_List.getCellData(Number(obj), "ACPT_NO");
    scwin.gSeq = dts_List.getCellData(Number(obj), "SEQ");
    scwin.gIsurCd = dts_List.getCellData(Number(obj), "ISUR_CD");
    // alert("부모창:"+gAcptNo+","+ gIsurCd);

};

/**
 * @method
 * @name popupNew
 * @description popup New 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popupNew = async function() {
    scwin.gAcptNo = '';
    scwin.gSeq = '';
    scwin.gIsurCd = '';
    let gGridNewYn = 'N';
    await scwin.popupDetail(gGridNewYn);
};

/**
 * @method
 * @name popupDetail
 * @description popup Detail 처리
 * @param {String} gGridNewYn gGridNewYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popupDetail = async function(gGridNewYn) {
    // var url = "/dsclmgt/ULDSTF37011.gfm";
    // var winTitle ="불성실공시법인적용예외 보고서";
    // frame.CreateDialogFrame("ULDSTF37011", url , winTitle ,100, -10, 710,  750+30, "window" );
    let url = "/dsclmgt/ULDSTF37011.gfm?";
    // url += "&ACPT_NO=" + gAcptNo;
    url += "&SEQ=" + scwin.gSeq;
    url += "&ISUR_CD=" + scwin.gIsurCd;
    url += "&GRID_NEW_YN=" + gGridNewYn;
    url += "&EXCPT_TP_CD=" + scwin.gExcptTpCd;
    url += "&frameID=" + frame.FrameID;
    if (await scwin.setParam(scwin.gSeq, scwin.gIsurCd)) {
        // formal arguments
        $c.frame.path("../../").GWinOpen("ULDSTF37011", url, "불성실예외처리법인관리 상세", 100, -10, 710, 750 + 40, "");
    }
};

/**
 * @method
 * @name setParam
 * @description child에 param을 넘긴다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) === "undefined") {
        await $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    let gGridNewYn = 'N';
    if (colid === "PUBL_DDTM") {
        if (scwin.gAcptNo !== '') {
            await $c.stf.openDisclViewer(scwin.gAcptNo, "R");
        } else {
            await $c.win.alert("해당 공시가 없습니다.");
        }
    } else if (colid === "NFAITH_DESIGN_EXCPT_RSN_NM") {
        await scwin.popupDetail(gGridNewYn);
    } else if (colid === "GRID_NEW_YN") {
        gGridNewYn = 'Y';
        await scwin.popupDetail(gGridNewYn);
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};

